import{_ as a,o as r,c as d,a2 as e}from"./chunks/framework.wVcpyw2-.js";const u=JSON.parse('{"title":"圈子与笔记","description":"灵萌圈子与笔记后台配置：笔记配置各 Tab、审核策略、圈子管理、热帖精帖与验收步骤。","frontmatter":{"title":"圈子与笔记","description":"灵萌圈子与笔记后台配置：笔记配置各 Tab、审核策略、圈子管理、热帖精帖与验收步骤。"},"headers":[],"relativePath":"features/circle-note.md","filePath":"features/circle-note.md","lastUpdated":1785020677000}'),o={name:"features/circle-note.md"};function h(i,t,l,n,s,b){return r(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="圈子与笔记" tabindex="-1">圈子与笔记 <a class="header-anchor" href="#圈子与笔记" aria-label="Permalink to &quot;圈子与笔记&quot;">​</a></h1><p>管理用户笔记内容、圈子与入圈审核，并按区域控制发布规则。这是校园社区最常用的一组配置。</p><hr><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>已创建至少一个区域：<strong>区域管理 → 区域列表</strong>（见 <a href="/config/region">区域管理</a>）</li><li><a href="/features/storage">文件存储</a> 已配好（否则无法传图）</li><li>客户端首页/发现页已用 <a href="/features/ui-editor/">UI 编辑器</a> 放好笔记列表等组件</li></ul><hr><h2 id="建议配置顺序" tabindex="-1">建议配置顺序 <a class="header-anchor" href="#建议配置顺序" aria-label="Permalink to &quot;建议配置顺序&quot;">​</a></h2><table tabindex="0"><thead><tr><th>顺序</th><th>菜单</th><th>做什么</th></tr></thead><tbody><tr><td>1</td><td><strong>区域管理 → 笔记配置</strong></td><td>开启发帖、评论、审核模式</td></tr><tr><td>2</td><td><strong>社交圈子 → 圈子分类</strong></td><td>建分类</td></tr><tr><td>3</td><td><strong>社交圈子 → 圈子管理</strong></td><td>建圈子并绑区域</td></tr><tr><td>4</td><td><strong>区域管理 → 笔记热度 / 热帖精帖配置</strong></td><td>按需调热度与标签</td></tr><tr><td>5</td><td><strong>UI管理 → 页面配置</strong></td><td>首页放筛选标签 + 笔记列表</td></tr></tbody></table><hr><h2 id="一、笔记配置-最重要" tabindex="-1">一、笔记配置（最重要） <a class="header-anchor" href="#一、笔记配置-最重要" aria-label="Permalink to &quot;一、笔记配置（最重要）&quot;">​</a></h2><p>路径：<strong>区域管理 → 笔记配置</strong></p><p>先选 <strong>平台默认</strong> 或具体区域，再按 Tab 配置，最后 <strong>保存配置</strong>。</p><p>未单独配置的区域会回退到平台默认（region_id = 0）。</p><h3 id="tab-基础功能" tabindex="-1">Tab：基础功能 <a class="header-anchor" href="#tab-基础功能" aria-label="Permalink to &quot;Tab：基础功能&quot;">​</a></h3><p>常见开关（以页面为准）：</p><table tabindex="0"><thead><tr><th>开关</th><th>作用</th></tr></thead><tbody><tr><td>允许纯文字 / 图片 / 视频 / 音频</td><td>控制能发什么</td></tr><tr><td>启用笔记标题</td><td>发布页是否要标题</td></tr><tr><td>发布页 AI 助手</td><td>需 <a href="/features/ai">AI 中台</a></td></tr><tr><td>启用地理位置 / 投票 / 蹲一蹲 / 举报</td><td>互动能力</td></tr><tr><td>启用相关推荐</td><td>需搜索推荐能力</td></tr><tr><td>区域发布入口、共创笔记、笔记置顶</td><td>入口与运营能力</td></tr><tr><td>允许用户创建圈子</td><td>用户可否自建圈</td></tr><tr><td>沉浸式圈子首页</td><td>圈子页体验</td></tr><tr><td>发布弹窗模板</td><td>发布入口样式（列表/双列等）</td></tr></tbody></table><h3 id="tab-评论设置" tabindex="-1">Tab：评论设置 <a class="header-anchor" href="#tab-评论设置" aria-label="Permalink to &quot;Tab：评论设置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>开关</th><th>作用</th></tr></thead><tbody><tr><td>允许评论</td><td>总开关</td></tr><tr><td>匿名评论 / 匿名笔记</td><td>配合匿名管理</td></tr><tr><td>允许用户自建匿名身份、自建需审核</td><td>匿名运营策略</td></tr><tr><td>作者置顶评论</td><td>楼主置顶</td></tr><tr><td>智能评论总开关 / AI 智能回复 / 评论摘要</td><td>快捷开关；高级项见 <a href="/features/ai-comment">智能评论</a></td></tr></tbody></table><h3 id="tab-权限认证" tabindex="-1">Tab：权限认证 <a class="header-anchor" href="#tab-权限认证" aria-label="Permalink to &quot;Tab：权限认证&quot;">​</a></h3><table tabindex="0"><thead><tr><th>开关</th><th>作用</th></tr></thead><tbody><tr><td>发布/评论强制绑定手机</td><td>提高门槛</td></tr><tr><td>强制学生认证</td><td>需先配学生认证流程</td></tr><tr><td>发布必须选择圈子 / 话题</td><td>强制归类</td></tr><tr><td>允许编辑 / 删除 / 下载图片</td><td>用户能力</td></tr><tr><td>区域负责人可编辑删除笔记与评论</td><td>下放治理权</td></tr></tbody></table><h3 id="tab-审核设置" tabindex="-1">Tab：审核设置 <a class="header-anchor" href="#tab-审核设置" aria-label="Permalink to &quot;Tab：审核设置&quot;">​</a></h3><p>重点：<strong>笔记发布模式</strong></p><table tabindex="0"><thead><tr><th>模式</th><th>表现</th></tr></thead><tbody><tr><td>先审后发</td><td>用户发了先进入待审，通过后才公开展示</td></tr><tr><td>审核发布（先发后审）</td><td>先展示，后台再审，不合规再下架</td></tr></tbody></table><p>强管控社区建议「先审后发」+ <a href="/config/forbidden-words">全局违禁词</a>「拒绝」。</p><h3 id="其他-tab" tabindex="-1">其他 Tab <a class="header-anchor" href="#其他-tab" aria-label="Permalink to &quot;其他 Tab&quot;">​</a></h3><ul><li><strong>内容限制</strong>：字数、图片数等</li><li><strong>浏览量</strong>：计数相关</li><li><strong>文案配置</strong>：提示文案定制</li></ul><hr><h2 id="二、热度与热帖精帖" tabindex="-1">二、热度与热帖精帖 <a class="header-anchor" href="#二、热度与热帖精帖" aria-label="Permalink to &quot;二、热度与热帖精帖&quot;">​</a></h2><table tabindex="0"><thead><tr><th>菜单</th><th>作用</th></tr></thead><tbody><tr><td><strong>区域管理 → 笔记热度</strong></td><td>热榜权重、算法参数</td></tr><tr><td><strong>区域管理 → 热帖精帖配置</strong>（或社交圈子下同名入口）</td><td>热帖/精帖标识规则</td></tr><tr><td><strong>社交圈子 → 热度日志</strong></td><td>查看热度变更，排障用</td></tr></tbody></table><p>调参后建议发几篇测试帖，观察排序与角标是否符合预期。</p><hr><h2 id="三、圈子管理" tabindex="-1">三、圈子管理 <a class="header-anchor" href="#三、圈子管理" aria-label="Permalink to &quot;三、圈子管理&quot;">​</a></h2><h3 id="圈子分类" tabindex="-1">圈子分类 <a class="header-anchor" href="#圈子分类" aria-label="Permalink to &quot;圈子分类&quot;">​</a></h3><p>路径：<strong>社交圈子 → 圈子分类</strong></p><p>先建分类（如「表白」「二手」「学习」），再建圈子时选用。</p><h3 id="圈子管理" tabindex="-1">圈子管理 <a class="header-anchor" href="#圈子管理" aria-label="Permalink to &quot;圈子管理&quot;">​</a></h3><p>路径：<strong>社交圈子 → 圈子管理</strong></p><ol><li>新建圈子：名称、封面、所属区域、是否公开、分类</li><li>设置负责人（如有）</li><li>保存后，客户端在对应用户区域可见</li></ol><h3 id="入圈申请" tabindex="-1">入圈申请 <a class="header-anchor" href="#入圈申请" aria-label="Permalink to &quot;入圈申请&quot;">​</a></h3><p>路径：<strong>社交圈子 → 入圈申请</strong></p><p>圈子为申请加入时，在此审核。</p><h3 id="笔记管理" tabindex="-1">笔记管理 <a class="header-anchor" href="#笔记管理" aria-label="Permalink to &quot;笔记管理&quot;">​</a></h3><p>路径：<strong>社交圈子 → 笔记管理</strong></p><p>日常下架、置顶、处理投诉内容。先审后发时，待审笔记也在此处理。</p><h3 id="匿名管理" tabindex="-1">匿名管理 <a class="header-anchor" href="#匿名管理" aria-label="Permalink to &quot;匿名管理&quot;">​</a></h3><p>路径：<strong>社交圈子 → 匿名管理</strong></p><p>维护匿名身份池；与笔记配置中的匿名开关配合。</p><hr><h2 id="四、话题-可选" tabindex="-1">四、话题（可选） <a class="header-anchor" href="#四、话题-可选" aria-label="Permalink to &quot;四、话题（可选）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>菜单</th><th>作用</th></tr></thead><tbody><tr><td>话题管理</td><td>话题列表</td></tr><tr><td>话题 PK / 话题活动</td><td>玩法</td></tr><tr><td>区域管理 → 话题配置</td><td>区域级开关</td></tr></tbody></table><p>详见 <a href="/features/vote-selection">投票与评选</a>。</p><hr><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><ol><li>笔记配置中该区域允许发图文笔记</li><li>客户端切到该区域，能打开发布页并成功发帖</li><li><strong>笔记管理</strong> 能看到；若先审后发，通过后用户端才展示</li><li>建一个测试圈子，用户能发现并申请/加入</li><li>首页 UI 已配置笔记列表时，新帖出现在信息流</li></ol><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>发不了笔记</td><td>笔记配置是否禁止内容类型；存储是否正常；用户是否被禁言</td></tr><tr><td>发了但别人看不见</td><td>是否先审后发未审；是否仅圈子可见；区域是否不一致</td></tr><tr><td>没有圈子入口</td><td>UI TabBar / 页面是否配置；圈子区域是否匹配</td></tr><tr><td>审核积压</td><td>笔记管理批量处理；或临时改为先发后审</td></tr><tr><td>AI 助手灰掉</td><td>AI 中台未配场景路由</td></tr></tbody></table><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/config/region">区域管理</a></li><li><a href="/config/forbidden-words">全局违禁词</a></li><li><a href="/features/ai-comment">智能评论</a></li><li><a href="/features/ui-editor/">UI 编辑器</a></li><li><a href="/features/vote-selection">投票与评选</a></li></ul>',60)])])}const f=a(o,[["render",h]]);export{u as __pageData,f as default};
